def mutate(path,edits):
 p=Path(path);before=p.read_text();after=before
 for old,new in edits:
  n=after.count(old)
  if n!=1:raise RuntimeError((path,n,old[:120]))
  after=after.replace(old,new,1)
 if p.name=='FloorGuideLayoutRegistry.cs':
  old='public static Mesh ResolveForRebuild(Mesh generated, string sourceAsset)\n        {'
  new='public static Mesh ResolveForRebuild(Mesh generated, string sourceAsset) =>\n            NamcheonSourceFrontRegistry.ResolveComposedForRebuild(ResolveBaselineForRebuild(generated, sourceAsset), sourceAsset);\n        // Existing baseline chain stays available for observed facade preflight before composition.\n        public static Mesh ResolveBaselineForRebuild(Mesh generated, string sourceAsset)\n        {'
  assert after.count(old)==1;after=after.replace(old,new)
